        'roomId': roomId,
        'actions': actions.map((e) => e.value).toList(),
        'validFor': validFor,
      };
}

/// Opaque identifier of one administrative power in the maintainer's capability
/// registry — lowercase dot-separated segments (e.g. `keys.sign`, `vtc.roles.assign`,
/// `git.repo.manage`). A consumer MUST NOT treat a capability it does not recognise as
/// granted.
typedef Capability = String;

/// Opaque qualifier naming the part of the maintainer's resources a capability applies
/// to (e.g. `git-ns:github.com/acme`, `git-repo:github.com/acme/r#4211`,
/// `policy:join`). Its grammar and containment rule are the maintainer's: a qualified
/// capability covers the named resource and the resources inside it. A qualifier MUST
/// NOT be read as widening the entry's act scope.
typedef ResourceQualifier = String;

/// A capability, optionally qualified by a resource. Used where a capability is named
/// but not granted — a role's ceiling, a role's approve ceiling, an entry's approvable
/// capabilities. An unqualified reference covers every resource of the capability's
/// kind.
class CapabilityRef {
  const CapabilityRef({
    required this.capability,
    this.resource,
  });

  /// Read this payload from a decoded JSON object.
  factory CapabilityRef.fromJson(Map<String, dynamic> json) => CapabilityRef(
        capability: json['capability'] as String,
        resource: json['resource'] as String?,
      );

  final Capability capability;

  /// Optional qualifier. Absent covers every resource of the capability's kind.
  final ResourceQualifier? resource;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'capability': capability,
        if (resource != null) 'resource': resource!,
      };
}

/// A grant set the group confers: each capability is written onto every member's
/// access-control entry as a resource grant whose source is the group, bounded by the
/// member's role ceiling and by the binder's own holdings.
class GrantsBindingSpec {
  const GrantsBindingSpec({
    required this.kind,
    required this.grants,
  });

  /// Read this payload from a decoded JSON object.
  factory GrantsBindingSpec.fromJson(Map<String, dynamic> json) =>
      GrantsBindingSpec(
        kind: json['kind'] as String,
        grants: (json['grants'] as List<dynamic>)
            .map((e) => CapabilityRef.fromJson(e as Map<String, dynamic>))
            .toList(),
      );

  final String kind;
  final List<CapabilityRef> grants;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'kind': kind,
        'grants': grants.map((e) => e.toJson()).toList(),
      };
}

/// A role identifier: lowercase, hyphen-separated, at most 64 characters. Compared by
/// exact string equality. It is the value an AclEntry 0.2 carries in `role`.
typedef RoleName = String;

/// A grant set by reference: the capability ceiling of a defined role, conferred as
/// resource grants exactly as a `grants` binding confers its list. It never assigns
/// the role itself — an entry's administrative role and its community role stay direct
/// assignments.
class RoleBindingSpec {
  const RoleBindingSpec({
    required this.kind,
    required this.role,
  });

  /// Read this payload from a decoded JSON object.
  factory RoleBindingSpec.fromJson(Map<String, dynamic> json) =>
      RoleBindingSpec(
        kind: json['kind'] as String,
        role: json['role'] as String,
      );

  final String kind;
  final RoleName role;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'kind': kind,
        'role': role,
      };
}

/// BindingSpec, defined by this specification's schema.
typedef BindingSpec = Object?;

/// BindingId, defined by this specification's schema.
typedef BindingId = String;

/// `pending`: waiting for the consent the community requires. `active`: in force; the
/// community's reconciler keeps members' admissions and grants in line with it.
/// `removing`: being withdrawn; the reconciler is removing what only this binding
/// provided.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const GroupBindingState(String value) {
  static const GroupBindingState pending = GroupBindingState('pending');
  static const GroupBindingState active = GroupBindingState('active');
  static const GroupBindingState removing = GroupBindingState('removing');

  /// Every value this specification's schema permits.
  static const List<GroupBindingState> values = <GroupBindingState>[
    pending,
    active,
    removing
  ];
}

/// GroupBinding
class GroupBinding {
  const GroupBinding({
    required this.bindingId,
    required this.binding,
    required this.state,
    required this.createdAt,
    this.createdBy,
  });

  /// Read this payload from a decoded JSON object.
  factory GroupBinding.fromJson(Map<String, dynamic> json) => GroupBinding(
        bindingId: json['bindingId'] as String,
        binding: json['binding'],
        state: GroupBindingState(json['state'] as String),
        createdAt: json['createdAt'] as String,
        createdBy: json['createdBy'] as String?,
      );

  final BindingId bindingId;
  final BindingSpec binding;

  /// `pending`: waiting for the consent the community requires. `active`: in force; the
  /// community's reconciler keeps members' admissions and grants in line with it.
  /// `removing`: being withdrawn; the reconciler is removing what only this binding
  /// provided.
  final GroupBindingState state;
  final String createdAt;
  final String? createdBy;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'bindingId': bindingId,
        'binding': binding,
        'state': state.value,
        'createdAt': createdAt,
        if (createdBy != null) 'createdBy': createdBy!,
      };
}
